mapper.select:
select ftp.FINPROD_ID as finprodId, ftp.FINPROD_TYPE2 as finprodType2, fpt.TYPE_6 as type6, DATE_FORMAT(ftp.VDATE, '%Y-%m-%d') as vdate, DATE_FORMAT(ftp.MDATE, '%Y-%m-%d') as mdate, ftp.EXC_PS as extPs, ftp.CCY as ccy, ftp.TERM as term, ftp.CONTRACT_NO as contractNo, ftp.CONTRACT_NAME as contractName, ftp.CALENDAR_ID as calendarId, mci.CALENDAR_NAME as calendarName, ftp.PRIN as prin, ftp.TRADE_MARKET as tradeMarket, ftpa.REGIST_ORG as registOrg, ftpa.OPT_FEE_PAY_TYPE as optFeePayType, ftpa.OPT_FEE_RATE as optFeeRate from FIN_TRADE_PRODUCT ftp left join FIN_PRODUCT_TYPE fpt on ftp.FINPROD_ID = fpt.FINPROD_ID left join FIN_TRADE_PRODUCT_ADD ftpa on ftp.FINPROD_ID = ftpa.FINPROD_ID left join MST_CALENDAR_INFO mci on mci.CALENDAR_ID = ftp.CALENDAR_ID where ftp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND ftp.FINPROD_ID = #{finprodId}
AND DATE_FORMAT(ftp.VDATE, '%Y-%m-%d') = #{vdate}
AND ftp.EXC_PS = #{extPs}
AND ftp.CCY = #{ccy}
AND ftpa.OPT_FEE_PAY_TYPE = #{optFeePayType}
